// Code panel: reference code of the current screen per platform (Jetpack Compose, SwiftUI, Flutter, React Native,
// React), generated by tools/screen_code.py into public/code/<slug>.json. Not production code: it shows how the screen
// is put together from the DS components and tokens. An element picked with Inspect highlights its lines.
// Desktop: a side panel. Phone width: a bottom sheet.
import React from 'react';

type PlatformCode = { label: string; ext: string; code: string; ranges: Record<string, [number, number]> };
type ScreenCode = { screen: string; slug: string; order?: string[]; platforms: Record<string, PlatformCode>; check?: { unknown: number; raw: number } };

const SHORT: Record<string, string> = { compose: 'Compose', swiftui: 'SwiftUI', flutter: 'Flutter', 'react-native': 'React Native', web: 'React' };
const cache: Record<string, Promise<ScreenCode | null>> = {};
function loadCode(slug: string) {
  if (!cache[slug]) {
    cache[slug] = fetch(`${import.meta.env.BASE_URL}code/${slug}.json`)
      .then((r) => (r.ok ? r.json() : null))
      .catch(() => null);
  }
  return cache[slug];
}

function remembered(): string | null {
  try { return window.localStorage.getItem('fp-code-platform'); } catch { return null; }
}
function remember(p: string) {
  try { window.localStorage.setItem('fp-code-platform', p); } catch { /* private mode */ }
}

async function copyText(text: string) {
  try {
    await navigator.clipboard.writeText(text);
    return true;
  } catch {
    const t = document.createElement('textarea');
    t.value = text;
    t.style.position = 'fixed';
    t.style.opacity = '0';
    document.body.appendChild(t);
    t.select();
    const ok = document.execCommand('copy');
    t.remove();
    return ok;
  }
}

export function CodePanel({ slug, picked, narrow, onClose }: { slug: string; picked: string[]; narrow: boolean; onClose: () => void }) {
  const [data, setData] = React.useState<ScreenCode | null | undefined>(undefined);
  const [platform, setPlatform] = React.useState<string | null>(remembered);
  const [copied, setCopied] = React.useState(false);
  const body = React.useRef<HTMLDivElement>(null);

  React.useEffect(() => {
    let live = true;
    setData(undefined);
    loadCode(slug).then((d) => { if (live) setData(d); });
    return () => { live = false; };
  }, [slug]);

  const order = data ? (data.order || Object.keys(data.platforms)).filter((p) => data.platforms[p]) : [];
  const active = platform && order.includes(platform) ? platform : order[0];
  const pc = data && active ? data.platforms[active] : null;

  // The first picked node (the tapped element, then its parents) that has lines in this platform's code.
  const range = React.useMemo(() => {
    if (!pc) return null;
    for (const id of picked) if (pc.ranges[id]) return { id, lines: pc.ranges[id] };
    return null;
  }, [pc, picked]);

  React.useEffect(() => {
    if (!range || !body.current) return;
    const el = body.current.querySelector(`[data-line="${range.lines[0]}"]`);
    if (el) el.scrollIntoView({ block: 'center', behavior: 'smooth' });
  }, [range, active]);

  const pick = (p: string) => { setPlatform(p); remember(p); setCopied(false); };
  const copy = async () => {
    if (!pc) return;
    const ok = await copyText(pc.code);
    setCopied(ok);
    if (ok) window.setTimeout(() => setCopied(false), 1600);
  };

  const lines = pc ? pc.code.replace(/\n$/, '').split('\n') : [];
  const frame = narrow
    ? 'fixed inset-x-0 bottom-0 z-30 flex h-[60vh] flex-col rounded-t-2xl border-t border-black/10 bg-white shadow-2xl dark:border-white/10 dark:bg-neutral-900'
    : 'flex w-[440px] shrink-0 flex-col border-l border-black/10 bg-white dark:border-white/10 dark:bg-neutral-900';

  return (
    <aside className={frame} aria-label="Reference code" data-code-panel={narrow ? 'sheet' : 'side'}>
      {narrow && <div aria-hidden="true" className="mx-auto mt-2 h-1 w-10 rounded-full bg-black/20 dark:bg-white/25" />}
      <div className="flex items-start gap-2 px-4 pb-2 pt-3">
        <div className="min-w-0 flex-1">
          <div className="text-sm font-semibold">Reference code</div>
          <div className="text-xs opacity-60">Not production code. Generated from Figma with DS names only.</div>
        </div>
        <button type="button" onClick={copy} disabled={!pc}
          className="rounded-md bg-black/5 px-2.5 py-1 text-xs font-medium hover:bg-black/10 disabled:opacity-40 dark:bg-white/10 dark:hover:bg-white/15">
          {copied ? 'Copied' : 'Copy'}
        </button>
        <button type="button" onClick={onClose} aria-label="Close code panel"
          className="rounded-md bg-transparent px-2 py-1 text-xs opacity-70 hover:bg-black/5 dark:hover:bg-white/10">✕</button>
      </div>
      <div role="tablist" aria-label="Platform" className="flex flex-wrap gap-1 px-4 pb-2">
        {order.map((p) => (
          <button key={p} type="button" role="tab" aria-selected={p === active} onClick={() => pick(p)} data-platform={p}
            className={`rounded-md px-2.5 py-1 text-xs ${p === active ? 'bg-neutral-900 text-white dark:bg-white dark:text-neutral-900' : 'bg-black/5 dark:bg-white/10'}`}>
            {narrow ? SHORT[p] || p : data!.platforms[p].label}
          </button>
        ))}
      </div>
      {range && (
        <div className="px-4 pb-1 text-xs opacity-70" data-code-highlight={range.id}>
          Lines {range.lines[0]}–{range.lines[1]} · Figma node {range.id}
        </div>
      )}
      <div ref={body} role="tabpanel" className="min-h-0 flex-1 overflow-y-auto border-t border-black/10 bg-neutral-50 py-2 dark:border-white/10 dark:bg-black/30">
        {data === undefined && <p className="px-4 text-xs opacity-60">Loading…</p>}
        {data === null && <p className="px-4 text-xs opacity-60">No reference code for this screen. Run tools/screen_code.py.</p>}
        {pc && (
          <pre className="m-0 font-mono text-[11.5px] leading-[1.55]" dir="ltr" lang="en">
            <code>
              {lines.map((l, i) => {
                const n = i + 1;
                const on = !!range && n >= range.lines[0] && n <= range.lines[1];
                return (
                  <div key={n} data-line={n} data-hl={on ? '' : undefined}
                    className={`flex gap-3 px-2 ${on ? 'bg-amber-300/30 shadow-[inset_3px_0_0_#d97706] dark:bg-amber-400/15' : ''}`}>
                    <span aria-hidden="true" className="w-7 shrink-0 select-none text-right opacity-40">{n}</span>
                    <span className="min-w-0 flex-1 whitespace-pre-wrap break-words">{l || ' '}</span>
                  </div>
                );
              })}
            </code>
          </pre>
        )}
      </div>
    </aside>
  );
}
